import{_ as o,C as r,o as s,c as i,j as t,a,E as d,a2 as l}from"./chunks/framework.Di-jvWLj.js";const x=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/index.md","filePath":"deployment/index.md","lastUpdated":1792515898000}'),p={name:"deployment/index.md"},c={id:"deployment",tabindex:"-1"};function h(u,e,m,g,b,y){const n=r("Badge");return s(),i("div",null,[t("h1",c,[e[0]||(e[0]=a("Deployment ",-1)),d(n,{type:"warning",text:"Planned"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#deployment","aria-label":'Permalink to "Deployment <Badge type="warning" text="Planned" />"'},"​",-1))]),e[3]||(e[3]=l(`<div class="warning custom-block"><p class="custom-block-title">Planned</p><p>The deploy kit does not exist yet. These pages describe the planned setup so you can see where chamberu is going. With <code>@chamberu/core</code> today you run the engine in your own Node process, start runs with <code>dispatch()</code> and shut down with <a href="/guide/recovery#drain"><code>drain()</code></a>.</p></div><p>The target workflow: agents live in their own GitHub repository, CI builds a Docker image, and Flux deploys it to your Kubernetes cluster. Every agent repository is an app with one or more agents, its own store connection, its own GitHub App and its own notifiers.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span>agent repo --push--&gt; CI --image--&gt; registry --Flux image automation--&gt; HelmRelease --&gt; cluster</span></span>
<span class="line"><span>                                                                            |</span></span>
<span class="line"><span>                                         OpenClaw --MCP--&gt; app (/mcp) --hooks--&gt; OpenClaw</span></span>
<span class="line"><span>                                         GitHub ---webhooks---&gt; app (/webhooks/github)</span></span></code></pre></div><h2 id="pieces" tabindex="-1">Pieces <a class="header-anchor" href="#pieces" aria-label="Permalink to &quot;Pieces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Planned as</th></tr></thead><tbody><tr><td><code>chamberu</code> package</td><td><code>createApp({ agents, store, notifiers, ... })</code> boots config, store, engine, scheduler and HTTP in order and tears them down in reverse, draining on <code>SIGTERM</code>. A CLI with <code>dev</code>, <code>build</code>, <code>start</code>, <code>run-job</code> and <code>migrate</code></td></tr><tr><td><a href="/deployment/docker">Base image</a></td><td>A slim Node 24 runtime image; agent repositories use a two-stage Dockerfile</td></tr><tr><td><a href="/deployment/kubernetes">Helm chart</a></td><td>One shared OCI chart for every agent app; each repository gets a small <code>HelmRelease</code></td></tr><tr><td>Template repository</td><td>A GitHub template with an example agent, Dockerfile, CI that builds and tags images for Flux, and example Flux manifests</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Planned configuration comes from environment variables, typically from Kubernetes Secrets: the database URL, <code>RESUME_SECRET</code>, the HTTP port, provider API keys (direct providers through the AI SDK provider registry, no gateway by default), static API tokens for machine clients, and OpenClaw and GitHub settings. How the Secrets get into the cluster (plain Secrets, SOPS, External Secrets) is the cluster&#39;s choice.</p><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><p>Planned: OpenTelemetry spans for runs and steps next to the AI SDK&#39;s own telemetry, Prometheus metrics from the HTTP app, and structured JSON logs.</p><h2 id="read-next" tabindex="-1">Read next <a class="header-anchor" href="#read-next" aria-label="Permalink to &quot;Read next&quot;">​</a></h2><ul><li><a href="/deployment/docker">Docker Image</a></li><li><a href="/deployment/kubernetes">Kubernetes &amp; Flux</a></li><li><a href="/deployment/replicas">Multiple Replicas</a></li><li><a href="/deployment/openclaw">OpenClaw</a></li><li><a href="/deployment/github-app">GitHub App</a></li></ul>`,11))])}const w=o(p,[["render",h]]);export{x as __pageData,w as default};
